class Solution {
public:
 long long splitArray(vector<int>& nums){int n=nums.size();vector<bool>prime(n,true);if(n>0)prime[0]=false;if(n>1)prime[1]=false;for(int p=2;p*p<n;++p)if(prime[p])for(int j=p*p;j<n;j+=p)prime[j]=false;
 long long a=0,b=0;for(int i=0;i<n;++i)(prime[i]?a:b)+=nums[i];return llabs(a-b);}
};
